INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-sbs-pdm','PRC-2026-006','PRJ-2026-004','SBS Blast Furnace Predictive Maintenance','B','active','u-arif','Instrument 42 critical blast-furnace assets at Sinar Baja with vibration and thermal sensing, stream the data to our IIoT platform and run anomaly detection that warns reliability engineers days before a failure.','Largest single engineering contract of 2026 and a reference site for heavy industry. One avoided BF-2 blower trip (≈ Rp 9 B lost production) pays for the programme; opens the hot-strip-mill and OT-segmentation follow-ons already in the pipeline.','Sensor selection, mounting and calibration on 42 assets (blowers, cooling fans, stoves, conveyors); edge gateways and plant-network integration with OSIsoft PI; anomaly models per asset class; operator alert workflow and 24-month platform subscription.','42 instrumented assets with calibration certificates; PI tag mapping; anomaly model v1 with per-asset thresholds; alert runbook; FAT/SAT reports. Accepted when 40 of 42 assets stream ≥ 98 % of samples for 30 days and SAT is signed.','Mechanical repairs found by the system; replacement of plant PLCs; cybersecurity remediation of the OT network (separate proposal d-sbs-ot).','≥ 98 % data availability; ≤ 3 false alerts per asset per month after tuning; at least one validated early warning in the first 90 days; gross margin ≥ 55 %.','2026-10-21T02:00:00.000Z','2027-02-26T10:00:00.000Z','[{"id":"ms-sbs-1","name":"BF-2 cooling & blower assets instrumented (14)","dueDate":"2026-10-30T10:00:00.000Z","paymentAmount":1400000000,"done":true},{"id":"ms-sbs-2","name":"BF-1 and hot-blast stoves instrumented (16)","dueDate":"2026-11-27T10:00:00.000Z","paymentAmount":1200000000,"done":false},{"id":"ms-sbs-3","name":"Remaining 12 assets + anomaly model tuning","dueDate":"2027-01-29T10:00:00.000Z","paymentAmount":2300000000,"done":false},{"id":"ms-sbs-4","name":"SAT sign-off and platform go-live","dueDate":"2027-02-26T10:00:00.000Z","paymentAmount":2000000000,"done":false}]','c-sbs','d-sbs-pdm','signed',0,60,'{"expected":6900000000,"best":7400000000,"worst":6200000000}','{"materials":1400000000,"subcontractors":350000000,"equipment":200000000,"travel":120000000,"other":80000000,"contingencyPct":10}','[{"id":"rk-sbs-1","category":"operational","description":"Sensor installation needs furnace-side access during planned outages only.","mitigation":"Install schedule locked to SBS outage calendar; pre-assembled mounting kits to halve time on site.","level":"high"},{"id":"rk-sbs-2","category":"technical","description":"Alert storms after furnace restarts erode operator trust.","mitigation":"Warm-up suppression windows and per-asset thresholds before go-live (IOT-205/206).","level":"medium"},{"id":"rk-sbs-3","category":"financial","description":"Sensor prices exposed to USD movements.","mitigation":"Supplier quotes fixed in IDR for the first two batches; 10 % contingency.","level":"low"}]',0,0,6,0.3,0,'2026-10-06T07:00:00.000Z','2026-10-07T03:00:00.000Z','u-fajar','{"feasibility":4,"profitability":5,"resources":3,"strategic":5,"risk":3,"notes":"Strong margin; resourcing tight because Dimas also technical-leads SPL. Net revenue above US$200k → 30 % deferral applies."}','{"outcome":"approved","rationale":"Signed client with payment history, margin well above threshold, strategic reference site.","conditions":"","conditionsDueAt":null,"votesFor":4,"votesAgainst":0,"ceoVeto":false,"decidedAt":"2026-10-20T08:00:00.000Z","decidedById":"u-ben"}',NULL,'2026-10-20T08:00:00.000Z',NULL,'e-pdm','2026-09-29T04:00:00.000Z','2026-11-03T09:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-spl-crane','PRC-2026-004','PRJ-2026-003','SPL Crane Telemetry Phase 2','B','active','u-rani','Extend the Phase 1 ship-to-shore crane telemetry at Priok Terminal to all 18 rubber-tyred gantries, with edge gateways that buffer data through cellular dropouts and feed the existing dashboards.','Protects and grows our largest recurring IIoT account; Phase 2 is the prerequisite for the Terminal Digital Twin (d-spl-twin, Rp 4.75 B) and the platform renewal.','Gateway installation on RTG-01 to RTG-18 in three batches; 72-hour store-and-forward buffering; PLC tag mapping; dashboard extension; operator training for the terminal engineering team.','18 RTGs streaming to the platform; batch handover packs; buffering firmware; training records. Accepted per batch once each crane streams ≥ 99 % of samples for 14 days.','Crane PLC upgrades; civil works; Navis N4 integration (Digital Twin scope).','≥ 99 % telemetry completeness per RTG; zero unplanned crane downtime caused by installation; batch handovers on schedule.','2026-10-01T02:00:00.000Z','2027-01-29T10:00:00.000Z','[{"id":"ms-spl-1","name":"Batch 1 — RTG-01 to RTG-06 live","dueDate":"2026-10-23T10:00:00.000Z","paymentAmount":1100000000,"done":true},{"id":"ms-spl-2","name":"Batch 2 — RTG-07 to RTG-12 live","dueDate":"2026-11-27T10:00:00.000Z","paymentAmount":950000000,"done":false},{"id":"ms-spl-3","name":"Batch 3 — RTG-13 to RTG-18 + final handover","dueDate":"2027-01-29T10:00:00.000Z","paymentAmount":1250000000,"done":false}]','c-spl-tpk','d-spl-crane','signed',0,45,'{"expected":3300000000,"best":3500000000,"worst":3000000000}','{"materials":720000000,"subcontractors":300000000,"equipment":60000000,"travel":90000000,"other":30000000,"contingencyPct":10}','[{"id":"rk-spl-1","category":"technical","description":"Cellular dead zones in the yard cause overnight telemetry gaps (seen on RTG-07).","mitigation":"Store-and-forward buffer (IOT-202) and modem sleep-policy fix before batch 2.","level":"high"},{"id":"rk-spl-2","category":"schedule","description":"Crane access windows depend on vessel schedules.","mitigation":"Weekly access plan agreed with terminal ops; two crews on call.","level":"medium"},{"id":"rk-spl-3","category":"reputation","description":"Failed gateways after power cuts (GW-14) visible to client management.","mitigation":"Hardware watchdog + remote reboot path; field support SLA 12 h.","level":"medium"}]',0,0,6,0.3,0,'2026-09-15T06:00:00.000Z','2026-09-16T03:00:00.000Z','u-maria','{"feasibility":5,"profitability":4,"resources":3,"strategic":4,"risk":4,"notes":"Proven Phase 1 design. Reviewer is Finance because initiator and lead sit on the PRC."}','{"outcome":"approved","rationale":"Repeat client, known design, healthy margin. Rani and Fajar recused.","conditions":"","conditionsDueAt":null,"votesFor":2,"votesAgainst":0,"ceoVeto":false,"decidedAt":"2026-09-28T08:00:00.000Z","decidedById":"u-ben"}',NULL,'2026-09-28T08:00:00.000Z',NULL,'e-crane','2026-09-08T03:00:00.000Z','2026-11-02T07:00:00.000Z');
