]','c-cam','d-cam-uas','signed',0,30,'{"expected":1380000000,"best":1450000000,"worst":1250000000}','{"materials":0,"subcontractors":40000000,"equipment":30000000,"travel":25000000,"other":14000000,"contingencyPct":10}','[{"id":"rk-cam-1","category":"schedule","description":"Regulator review queue could push approval past contract end.","mitigation":"Early informal review of the manual skeleton with the regulator.","level":"medium"},{"id":"rk-cam-2","category":"technical","description":"OEM torque tables conflict with legacy procedures.","mitigation":"Single source-of-truth table signed off by client engineering (ticket t-1004).","level":"low"}]',0,0,6,0.5,0,'2026-07-08T04:00:00.000Z','2026-07-09T02:00:00.000Z','u-fajar','{"feasibility":5,"profitability":5,"resources":4,"strategic":4,"risk":4,"notes":"Low-risk consulting; started under LOI, contract signed 5 Sep."}','{"outcome":"approved","rationale":"Existing client, pure consulting, margin above 60 %.","conditions":"","conditionsDueAt":null,"votesFor":4,"votesAgainst":0,"ceoVeto":false,"decidedAt":"2026-07-24T08:00:00.000Z","decidedById":"u-ben"}',NULL,'2026-07-24T08:00:00.000Z','2026-10-31T09:00:00.000Z',NULL,'2026-07-01T03:00:00.000Z','2026-11-03T04:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-nhs-seabed','PRC-2026-001','PRJ-2026-001','NHS Seabed Classification Model','A','active','u-sinta','Train a model that classifies multibeam backscatter into seabed classes for Nusantara Hydrographic, replacing days of manual interpretation per survey block, with a QC viewer for their hydrographers.','First AI product sold into maritime survey; reusable model IP and a beachhead for the vessel retrofit and fleet renewals at our largest maritime customer.','Data audit of the 2025 campaign; labelling with NHS hydrographers; baseline and production models; QC viewer; S-57 attribute export; handover and retraining guide.','Baseline evaluation report; production model ≥ 85 % class accuracy; QC viewer; S-57 export; retraining guide. Accepted on NHS sign-off of two pilot blocks.','Survey acquisition; bathymetry processing; hosting beyond 12 months.','≥ 85 % accuracy on held-out blocks; interpretation time per block reduced by 70 %; three payment milestones received.','2026-07-13T02:00:00.000Z','2026-12-18T10:00:00.000Z','[{"id":"ms-nhs-1","name":"Baseline model on 2025 campaign data","dueDate":"2026-08-14T10:00:00.000Z","paymentAmount":700000000,"done":true},{"id":"ms-nhs-2","name":"QC viewer + pilot classification of two blocks","dueDate":"2026-10-16T10:00:00.000Z","paymentAmount":500000000,"done":true},{"id":"ms-nhs-3","name":"Production model, S-57 export and handover","dueDate":"2026-12-11T10:00:00.000Z","paymentAmount":900000000,"done":false}]','c-nhs',NULL,'signed',0,120,'{"expected":2100000000,"best":2300000000,"worst":1900000000}','{"materials":0,"subcontractors":60000000,"equipment":45000000,"travel":20000000,"other":15000000,"contingencyPct":15}','[{"id":"rk-nhs-1","category":"financial","description":"120-day payment terms delay cash and bonus distribution.","mitigation":"Milestone billing; §6.3 deferral applied; Finance chases invoices at day 90.","level":"medium"},{"id":"rk-nhs-2","category":"technical","description":"Backscatter calibration differs between vessels.","mitigation":"Per-vessel normalisation layer and held-out validation by vessel.","level":"medium"},{"id":"rk-nhs-3","category":"operational","description":"Labelling depends on NHS hydrographer availability.","mitigation":"Labelling sprints booked in advance; vendor pre-labelling for review.","level":"low"}]',0,0,6,0.5,0,'2026-06-24T07:00:00.000Z','2026-06-25T02:00:00.000Z','u-maria','{"feasibility":4,"profitability":4,"resources":4,"strategic":5,"risk":3,"notes":"Payment terms > 90 days — 30 % deferral for 6 months."}','{"outcome":"approved","rationale":"Strategic AI reference with a key account; payment-term risk handled by deferral.","conditions":"","conditionsDueAt":null,"votesFor":4,"votesAgainst":0,"ceoVeto":false,"decidedAt":"2026-07-10T08:00:00.000Z","decidedById":"u-ben"}',NULL,'2026-07-10T08:00:00.000Z',NULL,'e-seabed','2026-06-15T03:00:00.000Z','2026-10-30T08:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-nhs-asv','PRC-2026-011',NULL,'NHS Autonomous Survey Vessel Retrofit','C','evaluation','u-sinta','Build and fit our autonomy retrofit kit v2 — autopilot, perception stack and remote-operations link — to two 9 m Nusantara Hydrographic survey launches, with a 12-month manufacturing warranty.','First production order for the vessel autonomy kit; turns our R&D into a product with a warranty-backed reference customer and a path to fleet-wide orders.','Kit v2 fabrication (2 units + spares); integration and harbour trials; sea trials and acceptance on both vessels; operator training (12 seats); 12-month warranty support.','Two retrofitted vessels passing the acceptance test procedure; spares kit; operator certification; warranty plan.','Hull or propulsion modifications; survey sensor supply; vessel crew.','Both vessels pass acceptance; ≥ 95 % autonomous line-keeping on survey runs; warranty claims < 5 % of contract value.','2026-12-01T02:00:00.000Z','2027-05-28T10:00:00.000Z','[{"id":"ms-asv-1","name":"Kit v2 factory acceptance (2 units)","dueDate":"2027-01-29T10:00:00.000Z","paymentAmount":2520000000,"done":false},{"id":"ms-asv-2","name":"Vessel 1 sea trials & acceptance","dueDate":"2027-03-26T10:00:00.000Z","paymentAmount":2940000000,"done":false},{"id":"ms-asv-3","name":"Vessel 2 acceptance + operator training","dueDate":"2027-05-28T10:00:00.000Z","paymentAmount":2940000000,"done":false}]','c-nhs','d-nhs-asv','loi',0,60,'{"expected":8400000000,"best":8900000000,"worst":7600000000}','{"materials":2600000000,"subcontractors":900000000,"equipment":400000000,"travel":180000000,"other":120000000,"contingencyPct":15}','[{"id":"rk-asv-1","category":"technical","description":"RTK multipath near quay walls (UAV-102) unresolved.","mitigation":"Dual-antenna heading and radar/camera fusion before factory acceptance.","level":"high"},{"id":"rk-asv-2","category":"financial","description":"Warranty exposure on a first production run.","mitigation":"Warranty reserve of 4 % of revenue; 12-month bonus deferral.","level":"high"},{"id":"rk-asv-3","category":"schedule","description":"Component lead times for perception sensors (12–16 weeks).","mitigation":"Long-lead items ordered on LOI at Spectrum risk, capped at Rp 600 M.","level":"medium"}]',0,1,12,NULL,0,'2026-11-02T03:00:00.000Z','2026-11-03T02:30:00.000Z','u-fajar','{"feasibility":4,"profitability":0,"resources":3,"strategic":5,"risk":0,"notes":"Profitability and risk pending Finance review of the warranty reserve. Dimas would reach 2.0/2.0 leadership capacity."}',NULL,NULL,NULL,NULL,NULL,'2026-10-12T03:00:00.000Z','2026-11-03T07:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-ptt-insp','PRC-2026-012',NULL,'PTT Drone Tower Inspection Programme','B','submitted','u-kevin','Automated drone inspection of 2,500 Pelita towers a year: generated flight plans, VTOL data capture and AI detection of corrosion, missing bolts and antenna defects, delivered as a maintenance work list.','Productises the tower defect model (SWD-303) into a recurring programme with a 9,400-site tower company; engineer-originated idea from the AI team.','Flight-plan generator per tower type; four VTOL airframes with operators; defect detection model v2; inspection portal; integration with PTT maintenance ticketing.','2,500 inspected towers per year with defect reports; inspection portal; model accuracy report ≥ 90 % recall on corrosion.','Climbing repairs; RF performance testing; permits for restricted airspace sites.','≥ 90 % corrosion recall; cost per tower 40 % below manual climb; 200 towers/month by month 3.','2026-12-07T02:00:00.000Z','2027-11-30T10:00:00.000Z','[{"id":"ms-ptt-1","name":"Pilot: 100 towers in Jabodetabek","dueDate":"2027-01-29T10:00:00.000Z","paymentAmount":600000000,"done":false},{"id":"ms-ptt-2","name":"Scale-up: 200 towers per month","dueDate":"2027-04-30T10:00:00.000Z","paymentAmount":2400000000,"done":false},{"id":"ms-ptt-3","name":"Year-1 completion (2,500 towers)","dueDate":"2027-11-30T10:00:00.000Z","paymentAmount":4200000000,"done":false}]','c-ptt','d-ptt-insp','none',1,60,'{"expected":7200000000,"best":7800000000,"worst":5900000000}','{"materials":200000000,"subcontractors":600000000,"equipment":1100000000,"travel":350000000,"other":150000000,"contingencyPct":10}','[{"id":"rk-ptt-1","category":"technical","description":"Model recall on heavy corrosion below target in coastal sites.","mitigation":"Vendor labelling batch 2 (SWD-304) focused on coastal towers.","level":"medium"},{"id":"rk-ptt-2","category":"operational","description":"Flight permits near airports and military zones.","mitigation":"Exclude restricted sites from year 1; PTT handles permits.","level":"medium"},{"id":"rk-ptt-3","category":"financial","description":"New client without payment history.","mitigation":"Monthly billing; §6.3 deferral; credit check by Finance.","level":"medium"}]',0,0,6,NULL,0,'2026-11-04T01:00:00.000Z',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-27T03:00:00.000Z','2026-11-04T01:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-twu-nrw','PRC-2026-007',NULL,'TWU Non-Revenue Water Analytics','A','conditional','u-nadia','Fuse pressure and flow data across six district metered areas at Tirta Water to localise leaks and rank pipe segments for repair, cutting non-revenue water in the pilot DMAs.','Opens the water-utility vertical; analytics IP reusable across municipal concessions; the leak-localisation POC (SWD-306) already shows promising results on DMA-3.','Data onboarding from ClearSCADA; sensor placement advice; leak localisation model per DMA; weekly repair priority list; quarterly NRW impact report.','Leak localisation model for 6 DMAs; weekly priority list; NRW impact reports; operator handover. Accepted when 70 % of top-10 flagged segments are confirmed by field crews.','Sensor hardware supply and installation (procured by TWU); pipe repairs.','NRW reduced by 5 percentage points in pilot DMAs within 6 months; ≥ 70 % field confirmation rate.','2026-11-16T02:00:00.000Z','2027-04-30T10:00:00.000Z','[{"id":"ms-twu-1","name":"Data onboarding & DMA baselines","dueDate":"2026-12-18T10:00:00.000Z","paymentAmount":600000000,"done":false},{"id":"ms-twu-2","name":"Leak localisation live in 6 DMAs","dueDate":"2027-02-26T10:00:00.000Z","paymentAmount":1000000000,"done":false},{"id":"ms-twu-3","name":"6-month NRW impact report","dueDate":"2027-04-30T10:00:00.000Z","paymentAmount":800000000,"done":false}]','c-twu','d-twu-nrw','loi',1,60,'{"expected":2400000000,"best":2600000000,"worst":2000000000}','{"materials":0,"subcontractors":180000000,"equipment":40000000,"travel":60000000,"other":30000000,"contingencyPct":10}','[{"id":"rk-twu-1","category":"technical","description":"SCADA data quality (gaps, unsynchronised clocks).","mitigation":"Two-week data audit before model work; clock alignment in ingestion.","level":"medium"},{"id":"rk-twu-2","category":"operational","description":"Field crews may not act on the priority list.","mitigation":"Weekly review with the NRW programme manager; confirmation tracked in the portal.","level":"medium"},{"id":"rk-twu-3","category":"financial","description":"Municipal budget cycle may delay payments.","mitigation":"Milestones aligned to TWU budget releases; contingency raised per PRC condition.","level":"low"}]',0,0,6,NULL,0,'2026-10-14T04:00:00.000Z','2026-10-15T02:00:00.000Z','u-rani','{"feasibility":4,"profitability":3,"resources":3,"strategic":4,"risk":3,"notes":"Contingency light for a new client; no QA/QC cover on a model-heavy delivery."}','{"outcome":"conditional","rationale":"Attractive new vertical and solid POC, but cost buffer and quality assurance are below standard for a first engagement with a new client.","conditions":"Raise contingency to 15% and add a QA/QC specialist before kickoff","conditionsDueAt":"2026-11-11T10:00:00.000Z","votesFor":3,"votesAgainst":1,"ceoVeto":false,"decidedAt":"2026-10-30T08:00:00.000Z","decidedById":"u-ben"}',NULL,NULL,NULL,NULL,'2026-10-05T03:00:00.000Z','2026-10-30T08:00:00.000Z');
INSERT INTO initiatives (`id`,`tracking_no`,`code`,`title`,`type`,`status`,`initiator_id`,`summary`,`value_proposition`,`scope`,`deliverables`,`exclusions`,`success_criteria`,`start_date`,`end_date`,`milestones`,`company_id`,`deal_id`,`contract_status`,`new_client`,`payment_terms_days`,`revenue`,`costs`,`risks`,`high_risk`,`warranty`,`deferral_months`,`locked_share_pct`,`cap_exception`,`submitted_at`,`acknowledged_at`,`primary_reviewer_id`,`scores`,`decision`,`appeal`,`approved_at`,`completed_at`,`epic_id`,`created_at`,`updated_at`) VALUES ('ini-mcd-light','PRC-2026-010',NULL,'MCD Smart Streetlight Network','B','rejected','u-dimas','Deploy 1,800 connected streetlight nodes with air-quality and flood sensors across Metro Cerdas''s new township, on a LoRaWAN backbone with a city operations dashboard.','Entry into smart-city infrastructure with a developer planning 1,200 ha of connected township; reusable node reference design (IOT-213).','Node reference design; 1,800 pole retrofits; LoRaWAN gateways; dashboard and alerting; 12-month maintenance.','1,800 live nodes; operations dashboard; maintenance plan. Accepted on 95 % node availability over 30 days.','Pole civil works; electricity supply; luminaire replacement.','95 % node availability; flood alerts within 5 minutes; gross margin ≥ 25 %.','2026-11-02T02:00:00.000Z','2027-03-31T10:00:00.000Z','[{"id":"ms-mcd-1","name":"Reference node design & pilot street (60 poles)","dueDate":"2026-12-18T10:00:00.000Z","paymentAmount":350000000,"done":false},{"id":"ms-mcd-2","name":"Phase 1 rollout (1,800 poles)","dueDate":"2027-03-31T10:00:00.000Z","paymentAmount":1600000000,"done":false}]','c-mcd','d-mcd-iot','none',1,90,'{"expected":1950000000,"best":2200000000,"worst":1200000000}','{"materials":900000000,"subcontractors":350000000,"equipment":80000000,"travel":40000000,"other":30000000,"contingencyPct":10}','[{"id":"rk-mcd-1","category":"financial","description":"Discovery-stage client with no LOI or payment history.","mitigation":"Require LOI and 20 % advance before procurement.","level":"high"},{"id":"rk-mcd-2","category":"technical","description":"Flood sensors untested in Bekasi drainage conditions.","mitigation":"Pilot street before committing to full rollout.","level":"medium"}]',0,0,6,NULL,0,'2026-10-21T06:00:00.000Z','2026-10-22T02:00:00.000Z','u-maria','{"feasibility":3,"profitability":2,"resources":2,"strategic":3,"risk":2,"notes":"Projected margin ~10 % after pool; Dimas has no leadership capacity left."}','{"outcome":"rejected","rationale":"Discovery-stage client without LOI; projected company margin below the 15 % threshold after the bonus pool; lead engineer at leadership capacity.","conditions":"","conditionsDueAt":null,"votesFor":1,"votesAgainst":3,"ceoVeto":false,"decidedAt":"2026-10-28T08:00:00.000Z","decidedById":"u-ben"}','{"filedAt":"2026-10-31T04:00:00.000Z","filedById":"u-dimas","reason":"New information: Metro Cerdas expects to issue an LOI with a 20 % advance in November, and a cheaper node BOM lifts projected margin to ~22 %. Requesting re-evaluation.","status":"pending","decidedAt":null,"notes":""}',NULL,NULL,NULL,'2026-10-12T03:00:00.000Z','2026-10-31T04:00:00.000Z');
